-- Live definition exported from the database (view nfl_player_seasons).
-- Do not edit here: change it with a migration; the next export will reflect it.

create or replace view public.nfl_player_seasons with (security_invoker=true) as
 WITH w AS (
         SELECT pw.player_id,
            pw.game_id,
            pw.season,
            pw.week,
            pw.season_type,
            pw.team,
            pw.opponent,
            pw."position",
            pw.completions,
            pw.attempts,
            pw.passing_yards,
            pw.passing_tds,
            pw.interceptions,
            pw.sacks,
            pw.passing_2pt,
            pw.carries,
            pw.rushing_yards,
            pw.rushing_tds,
            pw.rushing_2pt,
            pw.receptions,
            pw.targets,
            pw.receiving_yards,
            pw.receiving_tds,
            pw.receiving_2pt,
            pw.fumbles_lost,
            pw.special_teams_tds,
            pw.target_share,
            pw.air_yards_share,
            pw.wopr,
            pw.fg_made_0_39,
            pw.fg_made_40_49,
            pw.fg_made_50_plus,
            pw.fg_att,
            pw.fg_missed,
            pw.pat_made,
            pw.pat_missed,
            pw.src_points_std,
            pw.src_points_ppr,
            pw.imported_at,
            nfl.points_std(pw.*) AS s,
            tc.franchise AS fr,
            row_number() OVER (PARTITION BY pw.player_id, pw.season ORDER BY pw.week DESC) AS recency
           FROM (nfl.player_weeks pw
             JOIN nfl.team_codes tc ON ((tc.code = pw.team)))
          WHERE (pw.season_type = 'REG'::text)
        )
 SELECT w.player_id,
    p.slug AS player_slug,
    p.name AS player_name,
    (array_agg(w."position" ORDER BY w.week DESC))[1] AS "position",
    w.season,
    (array_agg(f.franchise ORDER BY w.week DESC))[1] AS team,
    (array_agg(f.slug ORDER BY w.week DESC))[1] AS team_slug,
    (array_agg(f.short_name ORDER BY w.week DESC))[1] AS team_short,
    count(*) AS games,
    sum(w.completions) AS completions,
    sum(w.attempts) AS attempts,
    sum(w.passing_yards) AS passing_yards,
    sum(w.passing_tds) AS passing_tds,
    sum(w.interceptions) AS interceptions,
    sum(w.carries) AS carries,
    sum(w.rushing_yards) AS rushing_yards,
    sum(w.rushing_tds) AS rushing_tds,
    sum(w.receptions) AS receptions,
    sum(w.targets) AS targets,
    sum(w.receiving_yards) AS receiving_yards,
    sum(w.receiving_tds) AS receiving_tds,
    sum(w.fumbles_lost) AS fumbles_lost,
    round(avg(w.target_share), 3) AS target_share,
    sum(((w.fg_made_0_39 + w.fg_made_40_49) + w.fg_made_50_plus)) AS fg_made,
    sum(w.fg_att) AS fg_att,
    sum(w.pat_made) AS pat_made,
    sum(w.s) AS pts_std,
    sum((w.s + (0.5 * (w.receptions)::numeric))) AS pts_half,
    sum((w.s + (w.receptions)::numeric)) AS pts_ppr,
    round(avg(w.s), 2) AS ppg_std,
    round(avg((w.s + (0.5 * (w.receptions)::numeric))), 2) AS ppg_half,
    round(avg((w.s + (w.receptions)::numeric)), 2) AS ppg_ppr,
    round(avg((w.s + (w.receptions)::numeric)) FILTER (WHERE (w.recency <= 3)), 2) AS last3_ppg_ppr,
    round(avg(w.s) FILTER (WHERE (w.recency <= 3)), 2) AS last3_ppg_std,
    round(avg((w.s + (0.5 * (w.receptions)::numeric))) FILTER (WHERE (w.recency <= 3)), 2) AS last3_ppg_half,
    round(stddev_pop((w.s + (w.receptions)::numeric)), 2) AS sd_ppr,
    max((w.s + (w.receptions)::numeric)) AS best_ppr,
    max(w.week) AS last_week
   FROM ((w
     JOIN nfl.players p ON ((p.player_id = w.player_id)))
     JOIN nfl.franchises f ON ((f.franchise = w.fr)))
  GROUP BY w.player_id, p.slug, p.name, w.season;
